export function exerciseGuide(id, instruction) {
  const extra = guides[id] || {
    group: 'other', muscle: instruction.muscles || 'Spiergroep uit je bewaarde schema',
    about: instruction.movement, equipment: instruction.setup,
    steps: [instruction.movement], mistakes: [instruction.avoid],
  };
  // The original setup, movement, cues and adaptations remain available verbatim.
  return { ...instruction, ...extra, name: displayName(instruction.name) };
}
